mapper.select:
SELECT M.MENUID,M.MLEVEL,M.MNAME,M.MSEQUENCE,M.MURL,M.PARENTID,M.MICON,M.MTYPE FROM T_ECC_MENU M
M.STATUS = '1' AND M.MTYPE='0'
AND M.PARENTID=#{sp.parentId}
AND M.MNAME LIKE '%' || #{sp.name} || '%'
AND M.MLEVEL =#{sp.level}
ORDER BY M.MSEQUENCE

SELECT P.MENUID,P.MLEVEL,P.MNAME,P.MSEQUENCE,P.MURL,P.PARENTID,P.MDESC,P.MCODE,P.MICON,P.MTYPE,M.MENUID MENUID1,M.MLEVEL MLEVEL1,M.MNAME MNAME1,M.MSEQUENCE MSEQUENCE1,M.MURL MURL1,M.PARENTID PARENTID1,M.MDESC MDESC1,M.MCODE MCODE1,M.MICON MICON1,M.MTYPE MTYPE1 FROM T_ECC_MENU P JOIN T_ECC_MENU M ON M.PARENTID=P.MENUID WHERE M.MTYPE='1' AND M.STATUS = '1'
AND ${inSQL}
ORDER BY M.PARENTID,M.MENUID

SELECT M.MENUID,M.MLEVEL,M.MNAME,M.MSEQUENCE,M.MURL,M.PARENTID,M.MDESC,M.MCODE,M.MICON,M.MTYPE FROM T_ECC_MENU M WHERE M.MTYPE='1' AND M.STATUS = '1'
AND ${inSQL}
ORDER BY M.PARENTID,M.MENUID

SELECT  M.MENUID,M.MLEVEL,M.MNAME,M.MSEQUENCE,M.MURL,M.PARENTID,M.MDESC,M.MCODE,M.MICON,M.MTYPE FROM T_ECC_EMP_MENU EM
	JOIN T_ECC_MENU M ON EM.MENUID =M.MENUID
	WHERE  M.STATUS = '1' AND  EM.EMPID=#{empId}

  SELECT  M.MENUID,M.MLEVEL,M.MNAME,M.MSEQUENCE,M.MURL,M.PARENTID,M.MDESC,M.MCODE,M.MICON,M.MTYPE FROM T_ECC_ORMEMBER_MENU OM  
	  JOIN T_ECC_MENU M ON OM.MENUID =M.MENUID
	  WHERE  M.MTYPE='1' AND  M.STATUS = '1' AND OM.ORGID =#{orgId} AND OM.TITLEID =#{titleId}

mapper.update:
UPDATE T_ECC_MENU M
 SET  M.STATUS = '0'

	M.MENUID = #{menuId}
